from taf.ul.ettf.utils.timeout import Timeout, raise_timeout_exception
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
from future.utils import with_metaclass
from abc import ABCMeta
import subprocess
import shlex
import psutil
import threading


command_logger = custom_logger('Command')
sudo_command_logger = custom_logger('SudoCommand')


DEFAULT_RUNNING_TIME = 5


def command_validation_check(command):
    assert command, 'Command should not be empty. Example: ifconfig eth1 down'


def not_sudo_command_validation_check(command):
    assert not command.strip().startswith('sudo'), 'Simple command should not start with sudo. For sudo commands use SudoCommand object'


def max_process_running_time_validation(max_process_running_time):
    assert max_process_running_time > 0.0, 'Max process running time should be greater than 0.0 seconds'


class CommandError(LibraryError):
    def __init__(self, msg):
        super(CommandError, self).__init__(exception_causes.COMMAND_ERROR, msg)


class CommandBase(with_metaclass(ABCMeta, object)):
    def __init__(self, command, logger):
        self._command = command
        self._logger = logger
        self._process = None
        self._error_occured = threading.Event()

    @typed(max_process_running_time=int)
    def run(self, max_process_running_time=DEFAULT_RUNNING_TIME):
        max_process_running_time_validation(max_process_running_time)
        self._logger.debug('Running command: {}'.format(self._command))
        output = ''

        with Timeout(timeout=max_process_running_time, timeout_handler=self._kill):
            try:
                self._process = subprocess.Popen(shlex.split(self._command))
                output, _ = self._process.communicate()
            except Exception:
                self._error_occured.set()
                self._logger.exception('Error raised during command execution')

        if self._error_occured.is_set():
            raise CommandError('Error occured during command execution')

        return output

    def _kill(self, *_):
        self._error_occured.set()
        if self._process is not None:
            process = psutil.Process(self._process.pid)
            for child in process.children(recursive=True):
                killing_process = subprocess.Popen(shlex.split('sudo kill -9 {}'.format(child.pid)))
                killing_process.communicate()

            killing_process = subprocess.Popen(shlex.split('sudo kill -9 {}'.format(self._process.pid)))
            killing_process.communicate()
            self._process = None
            command_logger.warn('Command was killed because of timeout. Command: {}'.format(self._command))
        raise_timeout_exception('Process killed')


class Command(CommandBase):
    def __init__(self, command):
        command_validation_check(command)
        not_sudo_command_validation_check(command)
        super(Command, self).__init__(command, command_logger)


class SudoCommand(CommandBase):
    def __init__(self, command):
        command_validation_check(command)
        super(SudoCommand, self).__init__('sudo {}'.format(command), sudo_command_logger)
